using System.ComponentModel.DataAnnotations;

namespace ProductCatalog.Api.Contracts;

/// <summary>
/// Payload used both to create (POST) and to fully replace (PUT) a product.
/// The id is intentionally absent: it is generated by the database and, for updates, taken from the route.
/// Validation is declarative (DataAnnotations); <c>[ApiController]</c> automatically answers
/// HTTP 400 with a <c>ValidationProblemDetails</c> body when it fails.
/// </summary>
public class ProductRequest
{
    /// <summary>Product name. Required, not blank, at most 200 characters.</summary>
    [Required(AllowEmptyStrings = false)]
    [StringLength(200, MinimumLength = 1)]
    public string Name { get; init; } = string.Empty;

    /// <summary>Optional description, at most 1000 characters.</summary>
    [StringLength(1000)]
    public string? Description { get; init; }

    /// <summary>
    /// Unit price, between 0.01 and 1,000,000. Declared nullable so that a *missing* value is
    /// rejected by <c>[Required]</c> instead of silently defaulting to 0.
    /// The range limits are parsed with the invariant culture; without that, machines whose culture uses a
    /// decimal comma (e.g. pt-PT) would fail to parse "0.01" and validation would throw.
    /// </summary>
    [Required]
    [Range(typeof(decimal), "0.01", "1000000",
        ParseLimitsInInvariantCulture = true,   // "0.01" is always parsed with a dot, whatever the machine's culture
        ConvertValueInInvariantCulture = true,  // the submitted value is converted the same way
        ErrorMessage = "Price must be between 0.01 and 1,000,000.")]
    public decimal? Price { get; init; }

    /// <summary>
    /// Initial/replacement stock, zero or greater. Nullable for the same reason as <see cref="Price"/>.
    /// </summary>
    [Required]
    [Range(0, int.MaxValue, ErrorMessage = "Stock must be zero or greater.")]
    public int? Stock { get; init; }
}